                if band_start <= c <= band_end:
                    col_band_start, col_band_end = band_start, band_end
                    break

            # Calculate position within band and flip
            pos_in_band = c - col_band_start
            flipped_pos = (col_band_end - col_band_start) - pos_in_band
            new_c = col_band_start + flipped_pos
            output[r, new_c] = grid[r, c]

# Set horizontal separators (entire rows of 8s)
for sep_row in [5, 11, 17, 23]:
    output[sep_row, :] = 8

# Fix any double assignments by only keeping original positions
